style.css:
@-moz-document url-prefix("https://www.youtube.com/") {
html, body, ytd-app {
    background: url("https://i.pinimg.com/originals/9e/84/72/9e8472b0ac8cfdc5ef24e4b3e2d3b5e7.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
    background-color: black !important;
  }

  #content.ytd-app, ytd-page-manager, ytd-watch-flexy, #page-manager {
    background-color: rgba(0, 0, 0, 0.6) !important;
    backdrop-filter: blur(4px) !important;
  }

  ytd-masthead, tp-yt-app-drawer {
    background-color: rgba(0, 0, 0, 0.7) !important;
  }

  /* Quitar el fondo blanco de algunos elementos */
  ytd-rich-grid-renderer, ytd-rich-item-renderer {
    background-color: transparent !important;
  }

  /* Cambiar el color del texto para mejor visibilidad */
  *, *::before, *::after {
    color: white !important;
  }
}
